output_text:
[
  {
    "id": "use_cart_for_shopping",
    "text": "A shopper must first take the available cart before doing any item pickup.",
    "abstraction": {
      "state_properties": {
        "at_cart_start": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "carrying_cart": "hasCart"
      },
      "events": {
        "cart_taken": {
          "pre": {
            "and": [
              "at_cart_start",
              "PICKUP_CART"
            ]
          },
          "post": "carrying_cart"
        },
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_taken"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Items should not be picked up unless the shopper currently has the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Groceries should not be carried by hand; they should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "holding_item_by_hand": "handFull",
        "cart_available_to_carry_items": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_available_to_carry_items"
              }
            ]
          },
          "post": "holding_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "holding_item_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_counter",
    "text": "After taking a cart, the shopper must eventually leave it at the cart-return counter at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_counter": "at(0,1)",
        "cart_parked_at_counter": "cartAt(0,1)",
        "carrying_cart": "hasCart"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "carrying_cart"
        },
        "cart_returned_to_counter": {
          "pre": {
            "and": [
              "cart_return_counter",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_counter"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned_to_counter"
    }
  },
  {
    "id": "only_leave_cart_at_counter",
    "text": "A cart may only be left at the designated return counter at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_counter": "at(0,1)",
        "away_from_return_counter": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "cart_left_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_return_counter"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_elsewhere"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper must not leave the store while still pushing the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "carrying_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "checkout_before_exit",
    "text": "Before exiting, the shopper must have performed the cart-return or checkout interaction at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "checkout_counter": "at(0,1)",
        "cart_parked_at_checkout": "cartAt(0,1)",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "checkout_or_cart_return": {
          "pre": {
            "and": [
              "checkout_counter",
              "INTERACT"
            ]
          },
          "post": "cart_parked_at_checkout"
        },
        "store_exit": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_or_cart_return"
    }
  },
  {
    "id": "after_return_do_not_retake_cart",
    "text": "Once the cart has been returned at cell (0,1), the shopper should proceed without taking a cart again.",
    "abstraction": {
      "state_properties": {
        "cart_return_counter": "at(0,1)",
        "cart_parked_at_counter": "cartAt(0,1)"
      },
      "events": {
        "cart_returned_to_counter": {
          "pre": {
            "and": [
              "cart_return_counter",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_counter"
        },
        "retake_returned_cart": {
          "pre": {
            "and": [
              "cart_parked_at_counter",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
